"""Writes pose_sheets.json and clips.json for v02. Frame numbers start at 0. A cell may serve several frames through `phase` (micro motion on one drawing). Poses come from v01; sizes and costume wording are for the large wings, tail and drapes."""
import json
from pathlib import Path

HERE = Path(__file__).parent
FACE = "Copy each cell's facing from Image 2: some cells face left or show her back. Seen from behind, her hair falls down her back between the large wings, the tail hangs below it and the arms stay outside the hair. In every pose the wings stay attached at her upper back and turn with her torso, the tail grows from her lower back, and the sleeve drapes hang from her upper arms; in leaps and fast moves they all trail behind the motion, and they never cover her forearms or hands. "

# name: (cell frames, size, cols, ref cells or None for all, {clip: (display name, [(slot, cell, phase or None)])}, motion, extras)
S = {}


def seq(frames, first_cell=0):
    return [(f, first_cell + k, None) for k, f in enumerate(frames)]


def sheet(name, frames, clips, motion, size="16:9", cols=4, ref=None, **extra):
    if name not in ("idle", "walk"):
        extra.setdefault("pad_y", 40)
    S[name] = dict(frames=frames, cols=cols, size=size, ref_cells=list(range(len(frames))) if ref is None else ref, clips=clips, motion=FACE + motion, **extra)


sheet("idle", [0, 4, 5, 6, 7, 8, 9, 11], {
    "待机": [(0, 0, 0), (1, 0, 0.5), (2, 0, 1), (3, 0, 1.5)],
    "待机抬手": seq([4, 5, 6, 7, 8], 1),
    "叉腰站": [(9, 6, 0), (10, 6, 0.5), (11, 7, 1), (12, 7, 1.5)],
}, "Cell 1: she stands relaxed in three-quarter view, the rear arm hanging with a closed fist low at the left of her hip, the front arm hanging at her side, hand visible. Cells 2 to 6 the front arm rises step by step while everything else holds: cell 2 the hand comes forward at hip height, cell 3 the open hand is at chest height in front of her, cells 4 and 5 it closes to a loose fist at chest height, cell 6 the fist pushes a little forward. As the arm rises, its sleeve drape lifts from the upper arm and hangs below the forearm, never covering the hand. Cells 7 and 8: feet wider apart, body turned more towards the viewer, the front hand on her waist with the elbow bent out to the right, the rear fist low at the left.")

